const fs=require('fs'),assert=require('assert');
const dir='updates';
const packages=fs.existsSync(dir)?fs.readdirSync(dir).filter(n=>/\.(?:ghupdate|saneiupdate)$/.test(n)):[];
// Build 242 changes protected source files. A previously signed package would be stale and unsafe;
// signed release packages must be regenerated by CI with the private Ed25519 key.
assert.strictEqual(packages.length,0,'Do not commit stale signed update packages after protected source changes; regenerate/sign in release CI.');
const build=fs.readFileSync('scripts/build_update.py','utf8');
assert(build.includes("'signaturePayloadVersion':2"),'release builder must emit signature payload v2');
assert(build.includes('sign_manifest(manifest)'),'release builder must require Ed25519 signing');
assert(build.includes('pause-x1-x2-x4'),'release builder speed contract must match four controls');
console.log('Update package source/release guard: PASS (signed package intentionally regenerated only in release CI)');
